    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

	function checkNonOwnerSendMoney(address _nonOwner) public {
		require(_nonOwner == c.owner());
		require(_nonOwner != address(this));
		bool ok; c.sendMoney(address(this), uint256(0), bytes("")); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
		assert(!ok);
	}
