        c = new SimpleWallet();
    }

    function _checkNonOwnerSendMoney(address _nonOwner) internal {
        _nonOwner = c.owner();
        vm.assume(_nonOwner != address(this));
        bool ok;
        try c.sendMoney(address(this), uint256(0), bytes("")) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }

    function testFuzz_checkNonOwnerSendMoney(address _nonOwner) public {
        _checkNonOwnerSendMoney(_nonOwner);
    }

